  'plans.autoRenewDisclosure': 'ການຈ່າຍເງິນຈະຖືກເກັບຈາກບັນຊີ Apple ຂອງເຈົ້າໃນການຢືນຢັນການຊື້. ສະຖານທີ່ຈະປ່ອນອີກຄັ້ງແບບບັດບັດເພີ່ມເຕີມແລະໄລຍະ, ນອກຈາກຖ້າຖືກລົງຄະແນນເບິ່ງ 24 ຊົ່ວໂມງກ່ຽວກັບສິ້ນສຸດຂອງໄລຍະປະຈຸບັນ. ຈັດການຫຼືລົງຄະແນນໃນເວລາໃດກໍ່ໃນການປັບປຸງ → [ຊື່ຂອງເຈົ້າ] → ສະຖານທີ່ສະຖານທີ່.',
