  'plans.familyIncludesPlus': 'ແບບບັດ Pro ຂອງເຈົ້າລວມທັງທ���ກຢ່າງຂອງ Chatyy Plus',
  'plans.storageWarning': 'ເຈົ້າກຳລັງໃຊ້ {used} ຈາກ {total}',
  'plans.storageWarningUpgrade': 'ເຮັດອັບເດດເພື່ອ Chatyy One ແລະໄດ້ 200 GB!',
  'plans.faqWhatIsPlus': 'Chatyy One ຄືຫຍັງ?',
  'plans.faqWhatIsPlusAnswer': 'ນີ້ແມ່ນແບບບັດສູງຂອງ Chatyy ທີ່ປົກປ່ອນທຸກສົນທະນາ, ຮູບພາບ ແລະວິດີໂອ. ກັບ Chatyy One, ເຖິງຖ້າເຈົ້າລົບສິ່ງໃດໃນບໍ່ຕໍ່ຄວາມສົນທະນາ, ສາມາດກູ້ໃນສິບ 30 ມື້. ນອກຈາກນັ້ນ, ເຈົ້າໄດ້ 200GB ສະຖານທີ່, One AI ເປັນຜູ້ຊ່ວຍສ່ວນບຸກຄົນ, ແລະສາມາດສົ່ງໄຟລ໌ເຖິງ 100MB.',
  'plans.faqCancelAnswer': 'ແບບບັດຂອງເຈົ້າຈະຍັງໃຊ້ແລ້ວຈົນສິ້ນສຸດຂອງໄລຍະທີ່ຈ່າຍແລ້ວ. ຫຼັງຈາກນັ້ນ, ເຈົ້າກັບໄປບັດບັດຟຣີ. ຮູບພາບ ແລະ ວິດີໂອທີ່ເກິນ 15GB ຈະຖືກຮັບສິດ���ນອີກ 30 ມື້ເພື່ອໃຫ້ເຈົ້າເຮັດດາວໂລດ.',
  'plans.faqHowFamily': 'ແບບບັດ Pro ດຳເນີນວຽກແນວໃດ?',
  'plans.faqHowFamilyAnswer': 'ເຈົ້າສາມາດເພີ່ມຄົນໄດ້ຈົນເຖິງ 4 ຄົນຈາກຄອບຄົວ. ທັງສິດສະຖານທີ່ 500GB ແລະຮັບສິດສະຖານທີ່ທັງສິດສະຖານທີ່ຂອງ Chatyy One. ທຸກຄົນມີສະຖານທີ່ສ່ວນບຸກຄົນ — ບໍ່ມີໃຜເບິ່ງໄຟລ໌ຂອງຄົນອື່ນ.',
  'plans.faqChangePlanAnswer': 'ແມ່ນ! ຖ້າເຈົ້າອັບເດດຈາກ Plus ສູ່ Pro, ຈະຖືກເກັບເງິນແຕ່ສ່ວນທີ່ຕ່າງກັນ. ຖ້າເຈົ້າລົງຄະແນນ, ແບບບັດປະຈຸບັນຈະຍັງໃຊ້ແລ້ວຈົນສິ້ນສຸດຂອງໄລຍະ.',
  'plans.faqCardDeclined': 'ບັດຂອງເຈົ້າຖືກປະຕິເສດ, ຂໍເຮັດແນວໃດ?',
  'plans.faqCardDeclinedAnswer': 'ເຈົ້າມີ 7 ມື້ເພື່ອ��ັບເດດບັດຂອງເຈົ້າ. ໃນເວລານັ້ນ, ສິດສະຖານທີ່ຂອງເຈົ້າຈະຍັງໃຊ້ແລ້ວ. ຫຼັງຈາກ 7 ມື້, ແບບບັດຈະກັບໄປບັດບັດຟຣີ.',
  'plans.faqDataSafe': 'ຂໍໍ່ຂອງເຈົ້າປອດໄພບໍ?',
  'plans.faqDataSafeAnswer': 'ແມ່ນ! ຂໍໍ່ຂອງເຈົ້າຖືກປະຕິເສດດ້ວຍການລູກຄ້າສູງສຸດ. ພວກເຮົາບໍ່ສາມາດບັນທຶກເລກບັດຂອງເຈົ້າ — ແຕ່ສິບ 4 ດິຈິດສຸດເພື່ອອ່ານ.',
  'plans.oneAI': 'One AI - ຜູ້ຊ່ວຍສ່ວນບຸກຄົນ',
  'plans.oneAIText': 'One AI ຊ່ວຍໃນການຂຽນແລະເຂົ້າໃຈຂໍໍ່',
  'plans.oneAISpreadsheet': 'One AI ຊ່ວຍໃນການຄິດໄລ່ແລະຂໍໍ່',
